// Line diff (longest common subsequence) with context collapsing, for the review step.
const MAX_CELLS = 2500000;
const CONTEXT = 3;

export function buildDiff(oldText, newText) {
    const a = (oldText || '').replace(/\r\n/g, '\n').split('\n');
    const b = (newText || '').replace(/\r\n/g, '\n').split('\n');
    let ops = [];

    if (a.length * b.length > MAX_CELLS) {
        a.forEach((t) => ops.push({ kind: 'del', text: t }));
        b.forEach((t) => ops.push({ kind: 'add', text: t }));
    } else {
        const n = a.length;
        const m = b.length;
        const dp = [];
        for (let i = 0; i <= n; i++) {
            dp.push(new Int32Array(m + 1));
        }
        for (let i = n - 1; i >= 0; i--) {
            for (let j = m - 1; j >= 0; j--) {
                dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
            }
        }
        let i = 0;
        let j = 0;
        while (i < n && j < m) {
            if (a[i] === b[j]) {
                ops.push({ kind: 'same', text: a[i] });
                i++;
                j++;
            } else if (dp[i + 1][j] >= dp[i][j + 1]) {
                ops.push({ kind: 'del', text: a[i++] });
            } else {
                ops.push({ kind: 'add', text: b[j++] });
            }
        }
        while (i < n) {
            ops.push({ kind: 'del', text: a[i++] });
        }
        while (j < m) {
            ops.push({ kind: 'add', text: b[j++] });
        }
    }

    // Keep CONTEXT unchanged lines around each change; collapse the rest.
    const keep = new Array(ops.length).fill(false);
    ops.forEach((op, idx) => {
        if (op.kind !== 'same') {
            for (let k = Math.max(0, idx - CONTEXT); k <= Math.min(ops.length - 1, idx + CONTEXT); k++) {
                keep[k] = true;
            }
        }
    });

    const lines = [];
    let added = 0;
    let removed = 0;
    let skipped = 0;
    let oldNo = 0;
    let newNo = 0;
    ops.forEach((op, idx) => {
        if (op.kind === 'add') {
            added++;
        }
        if (op.kind === 'del') {
            removed++;
        }
        if (op.kind !== 'add') {
            oldNo++;
        }
        if (op.kind !== 'del') {
            newNo++;
        }
        if (!keep[idx]) {
            skipped++;
            return;
        }
        if (skipped > 0) {
            lines.push({ id: 'gap' + idx, kind: 'gap', cls: 'line gap', sign: '', text: '… ' + skipped + ' unchanged lines' });
            skipped = 0;
        }
        lines.push({
            id: 'l' + idx,
            kind: op.kind,
            oldNo: op.kind === 'add' ? '' : oldNo,
            newNo: op.kind === 'del' ? '' : newNo,
            cls: op.kind === 'add' ? 'line add' : op.kind === 'del' ? 'line del' : 'line',
            sign: op.kind === 'add' ? '+' : op.kind === 'del' ? '-' : ' ',
            text: op.text
        });
    });
    if (skipped > 0) {
        lines.push({ id: 'gapend', kind: 'gap', cls: 'line gap', sign: '', text: '… ' + skipped + ' unchanged lines' });
    }
    return { lines, added, removed };
}

/**
 * Side-by-side rows from buildDiff lines: the target's version on the left, this org's on the right.
 * A run of removed lines is paired with the run of added lines after it.
 */
export function sideBySide(lines) {
    const rows = [];
    let i = 0;
    while (i < lines.length) {
        const l = lines[i];
        if (l.kind === 'gap') {
            rows.push({ id: 'r' + l.id, gap: true, text: l.text, leftCls: 'sbs-cell sbs-gap', rightCls: 'sbs-cell sbs-gap' });
            i++;
        } else if (l.kind === 'same') {
            rows.push({ id: 'r' + l.id, leftNo: l.oldNo, leftText: l.text, rightNo: l.newNo, rightText: l.text,
                leftCls: 'sbs-cell', rightCls: 'sbs-cell' });
            i++;
        } else {
            const dels = [];
            const adds = [];
            while (i < lines.length && lines[i].kind === 'del') {
                dels.push(lines[i++]);
            }
            while (i < lines.length && lines[i].kind === 'add') {
                adds.push(lines[i++]);
            }
            for (let k = 0; k < Math.max(dels.length, adds.length); k++) {
                const d = dels[k];
                const a = adds[k];
                rows.push({
                    id: 'r' + (d ? d.id : '') + (a ? a.id : ''),
                    leftNo: d ? d.oldNo : '', leftText: d ? d.text : '',
                    rightNo: a ? a.newNo : '', rightText: a ? a.text : '',
                    leftCls: 'sbs-cell' + (d ? ' sbs-del' : ' sbs-empty'),
                    rightCls: 'sbs-cell' + (a ? ' sbs-add' : ' sbs-empty')
                });
            }
        }
    }
    return rows;
}
